42	  "likewise", // 19:35, walk 9 — arrival 19:39: TOO LATE (tight)
43	  "monks", // 19:35, walk 10 — hidden at default 10-min budget? kept: exactly 10
44	  "shinjuku", // 19:35, walk 10
45	  "front-for-something", // 20:00, walk 8 — free
46	  "the-mysterious-seelie-wight-women", // 20:30, walk 4 — sold out (2nd)
47	  "abandoman-afterglow", // 20:55, walk 10 — sold out (3rd)
48	  // Ten more nearby on-sale shows so the all-genres list overflows one page
