1	// The requirements harness's browser: pinned Playwright Chromium, a hermetic
2	// fake origin served from disk, and every nondeterministic input replaced —
3	// clock, location, randomness, network (fonts, Leaflet, map tiles, geocoding,
4	// live data). Every UI case (screen and behavior kinds alike) gets its page
5	// from here, so "deterministic" is decided once, not per case.
6	//
7	// The page is served from a FAKE origin (http://edfringenow.req/), fulfilled
8	// entirely from the repo working tree + committed fixtures via route
9	// interception — no HTTP server process, no port, nothing off-disk. Any request
10	// the routing table doesn't recognise is aborted, so a new external dependency
11	// in the product breaks the suite loudly instead of adding hidden network.
12	"use strict";
13	
14	const fs = require("node:fs");
15	const os = require("node:os");
16	const path = require("node:path");
17	const { execSync } = require("node:child_process");
18	const { pathToFileURL } = require("node:url");
19	
20	const REPO_ROOT = path.join(__dirname, "..", "..", "..", "..");
21	// The served tree. The fake origin's "/" is the published site's root, not the
22	// repo's — the repo around it holds the scraper, the mount and the tooling, none
23	// of which a page can reach in production either.
24	const SITE_ROOT = path.join(REPO_ROOT, "site");
25	const VENDOR_DIR = path.join(__dirname, "vendor");
26	const FIXTURES_DIR = path.join(__dirname, "..", "fixtures");
27	const { REFERENCE_NOW_UTC_MS, TIMEZONE, LOCALE, GEOLOCATION } = require("../reference-now");
28	
29	// Rendering is only comparable against the committed goldens when the exact
30	// same Chromium rasterises it. This is the Playwright whose vendored browser
31	// the goldens were rendered with; the runner refuses to compare with any other.
32	const PINNED_PLAYWRIGHT = "1.56.1";
33	
34	// https, not http: geolocation only exists on secure origins. Routes are
35	// fulfilled before any real connection, so no certificate is involved.
36	const ORIGIN = "https://edfringenow.req";
37	
38	// The two committed viewports. A case says `viewport: "desktop"`; everything
39	// else about the screen (DPR 1, no touch) is fixed here.
40	const VIEWPORTS = {
41	  mobile: { width: 390, height: 844 },
42	  desktop: { width: 1280, height: 900 },
43	};
44	
45	const MIME = {
46	  ".html": "text/html; charset=utf-8",
47	  ".js": "text/javascript; charset=utf-8",
48	  ".mjs": "text/javascript; charset=utf-8",
49	  ".css": "text/css; charset=utf-8",
50	  ".json": "application/json; charset=utf-8",
51	  ".png": "image/png",
52	  ".svg": "image/svg+xml",
53	  ".webp": "image/webp",
54	  ".ico": "image/x-icon",
55	  ".woff2": "font/woff2",
56	  ".csv": "text/csv; charset=utf-8",
57	  ".txt": "text/plain; charset=utf-8",
58	};
59	
60	// Playwright resolves differently per environment: CI installs it into
61	// node_modules (a plain import), the Claude sandbox ships it globally beside a
62	// pre-provisioned browser. Try the local install first, then the global build
63	// by its ESM entry (the CJS index.js yields undefined named exports).
64	async function loadPlaywright() {
65	  try {
66	    return await import("playwright");
67	  } catch {
68	    /* no local install — fall through to the global build */
69	  }
70	  const guesses = ["/opt/node22/lib/node_modules/playwright/index.mjs"];
71	  try {
72	    guesses.push(path.join(execSync("npm root -g", { encoding: "utf8" }).trim(), "playwright", "index.mjs"));
73	  } catch {
74	    /* npm unavailable — the hardcoded guess still stands */
75	  }
76	  for (const g of guesses) {
77	    if (fs.existsSync(g)) return import(pathToFileURL(g).href);
78	  }
79	  throw new Error(
80	    "Playwright not found. Install the pinned version locally: npm i --no-save playwright@" +
81	      PINNED_PLAYWRIGHT +
82	      " && npx playwright install chromium"
83	  );
84	}
85	
86	function playwrightVersion() {
87	  const candidates = [
88	    path.join(REPO_ROOT, "node_modules", "playwright", "package.json"),
89	    "/opt/node22/lib/node_modules/playwright/package.json",
90	  ];
91	  for (const c of candidates) {
92	    if (fs.existsSync(c)) return JSON.parse(fs.readFileSync(c, "utf8")).version;
93	  }
94	  return null;
95	}
96	
97	// Deterministic Math.random for the page: mulberry32, fixed seed. Runs before
98	// any page script.
99	const SEEDED_RANDOM = `
100	  (() => {
101	    let s = 0xedf12026;
102	    Math.random = function () {
103	      s |= 0; s = (s + 0x6d2b79f5) | 0;
104	      let t = Math.imul(s ^ (s >>> 15), 1 | s);
105	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
106	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
107	    };
108	  })();
109	`;
110	
111	// Freeze every visual in flight: CSS animations/transitions land on their end
112	// state, the text caret never blinks, smooth scrolling is instant. Injected at
113	// document start so nothing renders un-frozen.
114	const FREEZE_CSS = `
115	  *, *::before, *::after {
116	    animation-duration: 0s !important;
117	    animation-delay: 0s !important;
118	    transition-duration: 0s !important;
119	    transition-delay: 0s !important;
120	    caret-color: transparent !important;
121	    scroll-behavior: auto !important;
122	  }
123	`;
124	
125	function fulfillFile(route, filePath, status = 200) {
126	  const ext = path.extname(filePath).toLowerCase();
127	  return route.fulfill({
128	    status,
129	    contentType: MIME[ext] || "application/octet-stream",
130	    body: fs.readFileSync(filePath),
131	  });
132	}
133	
134	// The released version is stamped into every published page, so the number the
135	// footer popup and the debug pill show would otherwise move on every release and
136	// take every golden with it. Serving the pages through here pins it: one
137	// substitution, applied to whatever the stamp currently says, so the goldens
138	// record the product rather than the day they were rendered.
139	const PINNED_VERSION = "0.0.0-spec";
140	const VERSION_STAMP = /title="version [^"]*"/g;
141	
142	function fulfillPage(route, filePath) {
143	  if (!filePath.endsWith(".html")) return fulfillFile(route, filePath);
144	  const html = fs.readFileSync(filePath, "utf8").replace(VERSION_STAMP, `title="version ${PINNED_VERSION}"`);
145	  return route.fulfill({ status: 200, contentType: MIME[".html"], body: html });
146	}
147	
148	// The routing table: URL → bytes, worked out once for the whole suite.
149	//   - our fake origin: fixtures override, then vendor, then the repo tree;
150	//   - Google Fonts CSS + unpkg Leaflet/markercluster: the committed vendor copies;
151	//   - OSM tiles: one committed fixture tile, whatever the coordinates;
152	//   - the geocoder: the committed fixture response (cases exercise "found");
153	//   - anything else: aborted.
154	async function routeAll(context, { dataDir, failData }) {
155	  await context.route("**/*", (route) => {
156	    const url = new URL(route.request().url());
157	    const { hostname, pathname } = url;
158	
159	    // Simulated outage: a case may declare URL substrings that must fail, to
160	    // drive the product's error states (a dead geocoder, a failed catalogue).
161	    if (failData && failData.some((s) => url.href.includes(s))) {
162	      return route.abort("failed");
163	    }
164	
165	    // Vendored assets, on ANY host: the fonts CSS is served from the Google
166	    // Fonts URL, so its url(/__vendor/…) references resolve against that host.
167	    if (pathname.startsWith("/__vendor/")) {
168	      const v = path.join(VENDOR_DIR, pathname.slice("/__vendor/".length).replace("fonts/", "fonts" + path.sep));
169	      if (fs.existsSync(v)) return fulfillFile(route, v);
170	      return route.abort();
171	    }
172	
173	    if (`${url.protocol}//${hostname}` === ORIGIN) {
174	      const rel = decodeURIComponent(pathname.replace(/^\/+/, "")) || "index.html";
175	      const withIndex = rel.endsWith("/") || rel === "" ? `${rel}index.html` : rel;
176	      // Live data is replaced wholesale by the committed fixture snapshot.
177	      if (withIndex.startsWith("data/")) {
178	        const fixture = path.join(dataDir, withIndex.slice("data/".length));
179	        if (fs.existsSync(fixture)) return fulfillFile(route, fixture);
180	        return route.fulfill({ status: 404, contentType: "text/plain", body: "no fixture" });
181	      }
182	      const onDisk = path.join(SITE_ROOT, withIndex);
183	      if (fs.existsSync(onDisk) && fs.statSync(onDisk).isFile()) return fulfillPage(route, onDisk);
184	      const asDir = path.join(SITE_ROOT, withIndex, "index.html");
185	      if (fs.existsSync(asDir)) return fulfillPage(route, asDir);
186	      return route.fulfill({ status: 404, contentType: "text/plain", body: "not found" });
187	    }
188	
189	    if (hostname === "fonts.googleapis.com") {
190	      return fulfillFile(route, path.join(VENDOR_DIR, "fonts", "fonts.css"));
191	    }
192	    if (hostname === "unpkg.com") {
193	      if (pathname.includes("/dist/images/")) {
194	        const img = path.join(VENDOR_DIR, "leaflet", "images", path.basename(pathname));
195	        if (fs.existsSync(img)) return fulfillFile(route, img);
196	      }
197	      const known = {
198	        "leaflet.css": "leaflet.css",
199	        "leaflet.js": "leaflet.js",
200	        "MarkerCluster.css": "MarkerCluster.css",
201	        "leaflet.markercluster.js": "leaflet.markercluster.js",
202	      }[path.basename(pathname)];
203	      if (known) return fulfillFile(route, path.join(VENDOR_DIR, "leaflet", known));
204	      return route.abort();
205	    }
206	    if (hostname.endsWith("tile.openstreetmap.org")) {
207	      return fulfillFile(route, path.join(FIXTURES_DIR, "tile.png"));
208	    }
209	    if (hostname === "photon.komoot.io" || hostname === "nominatim.openstreetmap.org") {
210	      return fulfillFile(route, path.join(FIXTURES_DIR, "geocode.json"));
211	    }
212	    return route.abort();
213	  });
214	}
215	
216	// ------------------------------------------------------------- font jail --
217	// The web fonts are vendored, but they are not the only fonts on the page: any
218	// character they don't carry — an emoji, an arrow, a Cyrillic show title — is
219	// drawn by whatever the *machine* has installed. That made the goldens a
220	// record of the renderer's font set, and CI's set is not the sandbox's: the
221	// walk-time line ("🚶 5 min · £16") measured a different width there and
222	// wrapped, making every card one line taller.
223	//
224	// So the harness gives Chromium its own fontconfig world: a generated config
225	// whose only font directory is `vendor/systemfonts/`, with the generic
226	// families aliased into it. Nothing installed on the host can reach the page.
227	const SYSTEM_FONTS_DIR = path.join(VENDOR_DIR, "systemfonts");
228	
229	function fontconfigFile() {
230	  const dir = path.join(os.tmpdir(), "edfringe-req-fontconfig");
231	  const cache = path.join(dir, "cache");
232	  fs.mkdirSync(cache, { recursive: true });
233	  const alias = (from, to) =>
234	    `  <alias binding="strong"><family>${from}</family><prefer><family>${to}</family></prefer></alias>`;
235	  const conf = `<?xml version="1.0"?>
236	<!DOCTYPE fontconfig SYSTEM "urn:fontconfig:fonts.dtd">
237	<fontconfig>
238	  <dir>${SYSTEM_FONTS_DIR}</dir>
239	  <cachedir>${cache}</cachedir>
240	${[
241	  alias("sans-serif", "DejaVu Sans"),
242	  alias("serif", "DejaVu Sans"),
243	  alias("monospace", "DejaVu Sans"),
244	  alias("system-ui", "DejaVu Sans"),
245	  alias("emoji", "Noto Color Emoji"),
246	  // The product's metric-matched fallback faces are `src: local("Arial")`.
247	  alias("Arial", "Liberation Sans"),
248	  alias("Helvetica", "Liberation Sans"),
249	].join("\n")}
250	</fontconfig>
251	`;
252	  const file = path.join(dir, "fonts.conf");
253	  fs.writeFileSync(file, conf);
254	  return file;
255	}
256	
257	let browserPromise = null;
258	
259	async function launchBrowser() {
260	  if (!browserPromise) {
261	    browserPromise = (async () => {
262	      const version = playwrightVersion();
263	      if (version && version !== PINNED_PLAYWRIGHT) {
264	        throw new Error(
265	          `Playwright ${version} found, but the goldens are rendered with ${PINNED_PLAYWRIGHT}. ` +
266	            "Rendering with a different Chromium makes every pixel comparison meaningless — install the pinned version."
267	        );
268	      }
269	      const { chromium } = await loadPlaywright();
270	      return chromium.launch({
271	        env: { ...process.env, FONTCONFIG_FILE: fontconfigFile() },
272	        args: [
273	          "--font-render-hinting=none",
274	          "--force-color-profile=srgb",
275	          "--disable-lcd-text",
276	          "--hide-scrollbars",
277	          // Shadow/blur rasterisation varies run-to-run without these: partial
278	          // raster reuses tiles whose seams land in blur corners.
279	          "--disable-partial-raster",
280	          "--disable-skia-runtime-opts",
281	          "--disable-gpu",
282	        ],
283	      });
284	    })();
285	  }
286	  return browserPromise;
287	}
288	
289	async function closeBrowser() {
290	  if (browserPromise) {
291	    const b = await browserPromise;
292	    await b.close();
293	    browserPromise = null;
294	  }
295	}
296	
297	/**
298	 * A fresh, fully-faked page for one case.
299	 * opts:
300	 *   viewport   "mobile" (default) | "desktop"
301	 *   dataDir    fixture data root (defaults to the committed snapshot)
302	 *   geolocation  override the fixed fake location, or null for "denied"
303	 *   colorScheme  the device's colour-scheme preference ("light" by default)
304	 *   localStorage {key: value} seeded on the fake origin before any page script
305	 *   nowUtcMs   override the pinned instant (rarely; the reference time is shared)
306	 */
307	async function newPage(opts = {}) {
308	  const browser = await launchBrowser();
309	  const geolocation = opts.geolocation === undefined ? GEOLOCATION : opts.geolocation;
310	  const context = await browser.newContext({
311	    viewport: VIEWPORTS[opts.viewport || "mobile"],
312	    deviceScaleFactor: 1,
313	    locale: LOCALE,
314	    // What the device asks for, which a page may follow and a reader may
315	    // override. Light unless a case says otherwise, so every existing golden
316	    // keeps the scheme it was rendered in.
317	    colorScheme: opts.colorScheme || "light",
318	    // The device's zone. Overridable so a case can prove the product reads
319	    // Edinburgh's clock rather than the device's — a context's zone is fixed at
320	    // creation, so showing two zones means two pages.
321	    timezoneId: opts.timezone || TIMEZONE,
322	    ...(geolocation
323	      ? { geolocation, permissions: ["geolocation"] }
324	      : { permissions: [] }),
325	  });
326	  await routeAll(context, {
