// Cloudflare Web Analytics — privacy-first, cookieless visitor counts.
//
// Cloudflare Web Analytics sets no cookies, stores no personal data, and can't
// track visitors across sites, so it needs no consent banner (see privacy.html).
//
// The beacon token is NOT a secret — it ships in the client and is visible to
// every visitor — so it lives in a GitHub Actions *variable* (not a secret):
//   repo Settings -> Secrets and variables -> Actions -> Variables ->
//   CLOUDFLARE_ANALYTICS_TOKEN
// The release substitutes it into the copy it uploads, so the committed file
// below always carries the placeholder and no checkout, fork or local preview
// ever beacons into the live site's numbers.
//
// TO ENABLE: create a free site in the Cloudflare dashboard (Web Analytics ->
// "Add a site"), then add its token as the CLOUDFLARE_ANALYTICS_TOKEN repo
// variable. With no variable set the placeholder ships and this loader no-ops,
// which the release says out loud either way.
//
// Until a real token is injected (variable unset, or running locally), this
// loader does nothing: no beacon is requested, so the site keeps its "no
// analytics" behaviour and never ships a broken tag.
(function () {
  var TOKEN = 'REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN';
  // Bail out while the placeholder is still in place (startsWith, ES5-safe).
  if (!TOKEN || TOKEN.lastIndexOf('REPLACE_WITH', 0) === 0) return;

  var beacon = document.createElement('script');
  beacon.defer = true;
  beacon.src = 'https://static.cloudflareinsights.com/beacon.min.js';
  beacon.setAttribute('data-cf-beacon', JSON.stringify({ token: TOKEN }));
  (document.head || document.documentElement).appendChild(beacon);
})();

/* The released version, read out of the page's own markup.
 *
 * Every page that shows a version carries `title="version <n>"` on its footer
 * line. That attribute is GENERATED — the release bumps package.json and stamps
 * each published page from it in the same run, and a check fails the build if
 * the two ever disagree. So the page already knows its version by the time it
 * loads, and no page fetches a file to find out.
 *
 * All three front-ends need exactly this, which is why it lives here rather
 * than three times over.
 */

/* Read the stamp, and take the attribute with it.
 *
 * Removing it matters: `title` is painted by the browser, outside the page, and
 * this site deliberately replaced that tooltip with a styled popup it can
 * position, key-navigate and screenshot (see version-popup.js). Leaving the
 * attribute in the live DOM would put the native tooltip back alongside the
 * popup that replaced it. The committed markup keeps it — that is what the
 * release stamps and the check reads — and the page drops it on load.
 *
 * Returns null when the page carries no stamp, which is every page that does
 * not show a version; callers treat that as "nothing to show". */
export function readVersionStamp(root = document) {
  const el = root.querySelector('[title^="version "]');
  if (!el) return null;
  const version = el.getAttribute("title").slice("version ".length).trim();
  el.removeAttribute("title");
  return version || null;
}

