1	/* A TTL cache for the JSON data files both pages download.
2	 *
3	 * The host serves every asset with `Cache-Control: public, max-age=0,
4	 * must-revalidate` and an ETag, so a browser re-checks every file on every load
5	 * and only saves the download itself. That is a round trip per data file, and
6	 * the catalogue is the bulkiest blocking one. So the freshness policy lives
7	 * here, on the client, where a file inside its window costs no request at all —
8	 * which no response header can offer — and each is given the lifetime its
9	 * *content* actually has:
10	 *
11	 *   - the catalogue the planner searches turns over rarely and is the bulkiest
12	 *     blocking download, so it is held for days;
13	 *   - ticket availability changes through the festival and is held for a day;
14	 *   - descriptions are effectively immutable and are held for a week.
15	 *
16	 * Payloads go into the Cache Storage API rather than localStorage, whose ~5 MB
17	 * ceiling the catalogue alone would breach. Cache Storage has no expiry of its
18	 * own, so the clock is kept beside it as a small localStorage map of
19	 * url -> epoch ms of the last fetch.
20	 *
21	 * Pure of any page: both index.html (js/app.js) and the planner (plan/plan.js)
22	 * resolve their relative data urls against the same origin, so they share one
23	 * cache and one stamp map, and a file fetched by either is reused by the other.
24	 */
25	
26	export const DAY_MS = 24 * 60 * 60 * 1000;
27	
28	const CACHE_NAME = "edfringe-data-v1";
29	const STAMPS_KEY = "edfringe.data.fetched.v1"; // url -> epoch ms of the last fetch
30	
31	export async function fetchJson(url) {
32	  const res = await fetch(url);
33	  if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
34	  return res.json();
35	}
36	
37	/* When each cached URL was last fetched. A plain localStorage map — the
38	 * payloads live in Cache Storage, this is only the clock beside them. */
39	function fetchStamps() {
40	  try {
41	    const raw = JSON.parse(localStorage.getItem(STAMPS_KEY) || "{}");
42	    return raw && typeof raw === "object" ? raw : {};
43	  } catch {
44	    return {};
45	  }
46	}
47	
48	function stampFetch(url) {
49	  try {
50	    localStorage.setItem(STAMPS_KEY, JSON.stringify({ ...fetchStamps(), [url]: Date.now() }));
51	  } catch {
52	    /* private mode / full quota — we just re-fetch next time */
53	  }
54	}
55	
56	function unstampFetch(url) {
57	  try {
58	    const stamps = fetchStamps();
59	    delete stamps[url];
60	    localStorage.setItem(STAMPS_KEY, JSON.stringify(stamps));
61	  } catch {
62	    /* as above — the worst case is one extra fetch */
63	  }
64	}
65	
66	/**
67	 * Throw away a cached copy we've judged unusable, clock and all.
68	 *
69	 * The clock matters as much as the payload: a stamp left behind keeps pointing
70	 * at an entry we've already rejected, so the next load makes the same bad
71	 * decision, and the next — for a day on availability, four days on the
72	 * catalogue.
73	 */
