1	// Fringe Planner — page logic.
2	//
3	// An ES module: shares no *globals* with the home site's js/app.js, but does
4	// share real code with it — anything both pages must agree on is imported from
5	// ../shared/, not copy-pasted. Wires the pure computation engine (./lib/*.js)
6	// to the UI.
7	//
8	// The page has one state switch, keyed on whether a favourites set is in — and
9	// it swaps only the *body* of the board: the drop stage (drag/drop or pick a
10	// favourites CSV) becomes the availability grid, at the same height, while the
11	// count line above it and the search bar below it stay put. The plan panel
12	// appears underneath. There is no "Plan" button — the itinerary recomputes live
13	// whenever the date window or any control changes.
14	
15	import { isInUK } from "../shared/geo.js";
16	import { cachedFetchJson, evictCached, DAY_MS } from "../shared/data-cache.js";
17	import { stayLink, travelLink } from "../shared/affiliates.js";
18	import { attachVersionPopup } from "../shared/version-popup.js";
19	import { readVersionStamp } from "../shared/version.js";
20	import { parseFavourites } from "./lib/favourites.js";
21	import { buildIndex, matchFavourites, summarize, buildSchedule, placementDiagnostics, slotKey } from "./lib/engine.js";
22	import { isAvailable } from "./lib/availability.js";
23	import { toCsv, toIcs, slotEndTime } from "./lib/itinerary.js";
24	import { distanceKm, travelMinutes } from "./lib/travel.js";
25	import { rehydrateShows, joinFingerprint } from "./lib/hydrate.js";
26	import {
27	  searchShows,
28	  catalogueFacets,
29	  catalogueVenues,
30	  hasActiveFilters,
31	  filterShows,
32	  matchFacets,
33	  showPrice,
34	  showAccessibility,
35	  ageLimitYears,
36	} from "./lib/search.js";
37	import { PRICE_OPTIONS, matchesPrice, priceLabel } from "../shared/price.js";
38	
39	// ES modules are always strict mode, so no "use strict" directive is needed.
40	
41	// --- Constants --------------------------------------------------------
42	
43	const DATA_URL = "../data/normalized/shows.min.json"; // compact catalogue; rehydrated against VENUES_URL
44	const VENUES_URL = "../data/venues.json"; // shared lookups (enums + venue map) the catalogue indexes into
45	const AVAILABILITY_URL = "../data/normalized/availability.min.json"; // per-performance ticket status
46	const DESCRIPTIONS_URL = "../data/normalized/descriptions.min.json"; // slug → full text, fetched lazily
47	
48	/* How long a downloaded data file may be reused before we ask the network
49	 * again (shared/data-cache.js). Each file gets the lifetime its content has,
50	 * which is the whole reason availability was split out of the catalogue:
51	 *
52	 *  - the catalogue is the bulkiest blocking download (3.0 MB, 948 KB gzipped)
53	 *    and now carries nothing that changes through the day, so four days of
54	 *    reuse costs a returning visitor only the shows added since;
55	 *  - availability is the one file that changes through the festival, so a day
56	 *    is the most it can be trusted — and it is far smaller than the catalogue,
57	 *    so the daily re-download is cheap;
58	 *  - venues.json is small and its lookup lists are append-only, so refetching
59	 *    it daily keeps it at least as new as any cached catalogue that indexes
60	 *    into it;
61	 *  - (the now page holds its day file for an hour, not a day — it draws SOLD
62	 *    OUT stamps and wants the freshest copy going; see js/app.js);
63	 *  - descriptions are effectively immutable, so a week means a returning
64	 *    visitor pays for them once. */
65	const CATALOGUE_TTL_MS = 4 * DAY_MS;
66	const AVAILABILITY_TTL_MS = DAY_MS;
67	const LOOKUPS_TTL_MS = DAY_MS;
68	const DESCRIPTIONS_TTL_MS = 7 * DAY_MS;
69	
70	const YEAR = 2026;
71	const MONTH = "08"; // August, 2-digit
72	const DAYS_IN_MONTH = 31; // Aug 1–31 is the axis this calendar draws.
73	const FEST_START_DAY = 7; // The Fringe runs Fri 7 – Sun 31 Aug 2026; days 1–6 draw as a shaded "before it opens" zone.
74	
75	const T_MIN = 0; // 00:00 — the calendar's catchable-count filter never narrows on start time.
76	const T_MAX = 1440; // 24:00
77	
78	const DEFAULT_D0 = 7; // default date window: Aug 7 → Aug 24 (the festival trip window)
79	const DEFAULT_D1 = 24;
80	
81	// The schedule axis, and the range a "day ends" can reach: a Fringe evening
82	// runs past midnight, so the day is drawn from 09:00 to 27:00 (03:00) and a show
83	// may be allowed to finish any time up to that late edge.
84	const AXIS_TOP_MIN = 9 * 60; // 09:00 — top of every day column
85	const AXIS_BOTTOM_MIN = 27 * 60; // 27:00 = 03:00 — bottom of every day column
86	const DAY_END_CEIL = AXIS_BOTTOM_MIN; // a "day ends" can be set as late as 27:00
87	
88	// Default day-hours window (minutes of day). The day ends at 25:00 (01:00) by
89	// default so ordinary late-night shows are catchable out of the box.
90	const DEFAULT_DAY_START = 9 * 60; // 09:00
91	const DEFAULT_DAY_END = 25 * 60; // 25:00 = 01:00
92	
93	const STORAGE_KEY = "edfringe.plan.favourites.v1";
94	const TTL_MS = 3 * 24 * 60 * 60 * 1000; // keep for 3 days, then forget
95	
96	// Dismissed partner nags (see buildNag). Kept in its own key with no TTL: an "I
97	// don't need this" is an answer, not a stale cache, so it outlives the
98	// favourites it was dismissed over.
99	const NAGS_KEY = "edfringe.plan.nags.v1";
100	/* The scheduling preferences: the date window, day hours, meal breaks, the
101	 * arrival/departure blocks, travel mode, the pacing controls and the must-sees.
102	 * Its own key, like the two above — these shape *how* the plan is built, and a
103	 * visitor who set them expects them back on the next visit, so they must not
104	 * expire with the 3-day favourites TTL. */
105	const PREFS_KEY = "edfringe.plan.prefs.v1";
106	
107	// Genre → a small emoji drawn on the left of each scheduled block. Keys are the
108	// ten headline genres in shows.json; anything else falls back to a ticket.
109	const GENRE_EMOJI = {
110	  "Comedy": "😂",
111	  "Theatre": "🎭",
112	  "Cabaret and Variety": "🎪",
113	  "Children's Shows": "🧸",
114	  "Dance, Physical Theatre & Circus": "💃",
115	  "Events": "✨",
116	  "Exhibitions": "🖼️",
117	  "Music": "🎵",
118	  "Musicals and Opera": "🎶",
119	  "Spoken Word": "🗣️",
120	};
121	function genreEmoji(genre) {
122	  return GENRE_EMOJI[genre] || "🎟️";
123	}
124	
125	// Travel modes: emoji + a verb for the leg label ("12 min walk" / "by bike").
126	const MODE_META = {
127	  walk: { emoji: "🚶", verb: "walk" },
128	  bike: { emoji: "🚲", verb: "by bike" },
129	  car: { emoji: "🚗", verb: "by car" },
130	};
131	
132	// --- Small helpers ------------------------------------------------------
133	
134	const $ = (id) => document.getElementById(id);
135	const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
136	const pad2 = (n) => String(n).padStart(2, "0");
137	
138	/** "YYYY-MM-DD" for a day-of-month within August 2026. */
139	function dateStr(day) {
140	  return `${YEAR}-${MONTH}-${pad2(day)}`;
141	}
142	
143	/** "HH:MM" for a minute-of-day (caps at 23:59 for the 1440 sentinel). */
144	function minToHHMM(min) {
145	  const m = Math.min(1439, Math.max(0, Math.round(min)));
146	  return `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`;
147	}
148	/**
149	 * Extended-hours clock for a minute-of-day that may run past midnight: 1500 →
150	 * "25:00", 1470 → "24:30". Used for the "day ends" control and the after-hours
151	 * lines/labels on the 09:00–27:00 schedule axis.
152	 */
153	function minToDayClock(min) {
154	  const m = Math.max(0, Math.round(min));
155	  return `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`;
156	}
157	/** Parse an "HH:MM" time-input value to minutes of day (null if blank). */
158	function hhmmToMin(str) {
159	  if (!str) return null;
160	  const [h, m] = str.split(":").map(Number);
161	  if (Number.isNaN(h) || Number.isNaN(m)) return null;
162	  return h * 60 + m;
163	}
164	
165	// 1 Aug 2026 is a Saturday; compute weekday letters from real dates.
166	const DOW_SHORT = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];
167	function dow(day) {
168	  return new Date(Date.UTC(YEAR, 7, day)).getUTCDay();
169	}
170	function dowShort(day) {
171	  return DOW_SHORT[dow(day)];
172	}
173	function isWeekend(day) {
174	  const d = dow(day);
175	  return d === 0 || d === 6;
176	}
177	
178	// --- App state ------------------------------------------------------------
179	
180	const state = {
181	  index: null, // Map<slug, show> — the full catalogue
182	  catalogue: [], // the same catalogue as an array — what the show search scans
183	  lookups: null, // venues.json lists (genres, subgenres, …) — the search filters' options
184	  facets: null, // catalogueFacets() over the catalogue: which optional facets have data
