243	// --- Data loading + rehydration ---------------------------------------
244	//
245	// The planner downloads three files up front: the compact catalogue
246	// (shows.min.json, packed by scraper/normalize.py), the shared lookups
247	// (venues.json) and the availability sidecar (availability.min.json).
248	// rehydrateShows() (./lib/hydrate.js) joins them back into the full records the
249	// engine expects — every enum is an index into a venues.json list, venueName is
250	// rebuilt from the venue code + room, dates are MMDD ints, the bare image GUID
251	// gets its host prefix re-attached, and each performance picks up its ticket
252	// status from the sidecar — so the rest of the app sees a ready-to-use
253	// catalogue identical in shape to the old shows.json.
254	//
255	// The three are split the way they are so each can be cached for as long as its
256	// contents actually last: see the TTL constants above. Availability is the only
257	// one of them that moves through the day, and it is the smallest.
258	//
259	// A fourth file — the descriptions sidecar — follows *after* those have landed,
260	// and nothing waits for it: see loadDescriptions.
261	
262	/* What each file has to look like before we'll build a planner out of it.
263	 *
264	 * These exist because a cached copy from an older generation of a file parses
265	 * perfectly and then joins to nothing — no exception, no console line, just a
266	 * planner quietly reporting that the whole festival is unavailable (#309). The
267	 * sidecar has carried a `v` for this all along; nothing was reading it. Kept
268	 * deliberately shallow: enough to tell "this is the file I think it is" from
269	 * "this is something else", not a schema validator. */
270	const isCatalogue = (d) => Array.isArray(d) && d.length > 0;
271	const isLookups = (d) => Boolean(d) && typeof d.venues === "object" && d.venues !== null;
272	const isAvailabilitySidecar = (d) =>
273	  Boolean(d) && d.v === 1 && Array.isArray(d.ts) && d.ts.length > 0 &&
274	  Boolean(d.a) && typeof d.a === "object" && Object.keys(d.a).length > 0;
275	
276	/* How much of the catalogue must come back with a ticket status before we are
277	 * willing to draw it.
278	 *
279	 * The catalogue is cached for four days and the sidecar for one, so they are
280	 * routinely joined across generations, and a few misses are the honest cost of
281	 * that: a show that added or dropped a date since the catalogue was packed
282	 * finds no status, which is exactly what the date-and-time naming scheme was
283	 * designed to do. Real drift over four days is a fraction of a percent.
284	 *
285	 * A systematic key change is a different animal. #274 corrected every start
286	 * time by an hour, and the next day's sidecar matched 6% of the previous day's
287	 * catalogue — 94% of the festival status-unknown, drawn as unavailable (#309).
288	 * Nothing between 6% and 99% is a state we can tell a coherent story about, so
289	 * the line sits where it separates drift from breakage rather than where it
290	 * splits the difference. */
291	const MIN_STATUS_COVERAGE = 0.9;
292	
293	/**
294	 * Do these two files describe the same festival?
295	 *
296	 * Two independent answers, because they fail in different places. The
297	 * fingerprint is exact and cheap and settles it outright — but only for a
298	 * sidecar new enough to carry one, which a cached copy predating that field
299	 * won't. Coverage is the fallback: approximate, but it reads the join itself
300	 * rather than a claim about it, so it also catches whatever the fingerprint
301	 * hasn't thought of.
302	 *
303	 * @returns {{ok: boolean, why?: string}}
304	 */
305	function joinIsSound(wire, availability, catalogue) {
306	  const stamped = availability && typeof availability.k === "string";
307	  if (stamped) {
308	    const mine = joinFingerprint(wire);
309	    if (mine !== availability.k) {
310	      return { ok: false, why: `catalogue ${mine} vs availability ${availability.k}` };
311	    }
312	  }
313	
314	  let performances = 0;
315	  let withStatus = 0;
316	  for (const show of catalogue) {
317	    for (const perf of show.performances || []) {
318	      performances++;
319	      if (perf.status) withStatus++;
320	    }
321	  }
322	  if (performances === 0) return { ok: true }; // an empty catalogue is a different problem
323	  const coverage = withStatus / performances;
324	  if (coverage < MIN_STATUS_COVERAGE) {
325	    return {
326	      ok: false,
327	      why: `only ${withStatus} of ${performances} performances (${Math.round(coverage * 100)}%) ` +
328	           "carry a ticket status",
329	    };
330	  }
331	  return { ok: true };
332	}
