334	/**
335	 * The three files the planner is built from, joined — refetched once from source
336	 * if the copies we were given don't agree with each other.
337	 *
338	 * All three are required. Availability used to be allowed to fail on the theory
339	 * that status-unknown is a state the grid already draws — it isn't. An empty
340	 * status reads as not-bookable everywhere downstream (isAvailable, segClass,
341	 * laneStatus), so continuing without the sidecar doesn't degrade the planner, it
342	 * inverts it: every performance turns red and every show reports "No dates", for
343	 * a festival that is very much on sale (#309).
344	 *
345	 * The retry is the substance. A generation disagreement is not a network failure
346	 * and not a corrupt file — it is two perfectly good files that have drifted
347	 * apart on their separate TTLs, and the fix is simply to go and get today's, so
348	 * that is what happens. Only if freshly-downloaded copies *still* disagree is
349	 * this a real failure, and then it belongs in the error panel: at that point we
350	 * genuinely don't know what's bookable, and a wrong plan is worse than no plan.
351	 */
352	async function loadCatalogue() {
353	  for (const attempt of [1, 2]) {
354	    const [wire, lookups, availability] = await Promise.all([
355	      cachedFetchJson(DATA_URL, CATALOGUE_TTL_MS, noteCache, isCatalogue),
356	      cachedFetchJson(VENUES_URL, LOOKUPS_TTL_MS, noteCache, isLookups),
357	      cachedFetchJson(AVAILABILITY_URL, AVAILABILITY_TTL_MS, noteCache, isAvailabilitySidecar),
358	    ]);
359	    const catalogue = rehydrateShows(wire, lookups, YEAR, availability);
360	    const verdict = joinIsSound(wire, availability, catalogue);
361	    if (verdict.ok) return { lookups, catalogue };
362	
363	    if (attempt === 2) {
364	      throw new Error(
365	        `the catalogue and the ticket availability don't match (${verdict.why})`
366	      );
367	    }
368	    // Drop both and go again. Which of the two is stale isn't knowable from
369	    // here — the catalogue's four-day TTL makes it the usual suspect, but a
370	    // sidecar can be the stale one too — and this costs one extra download of
371	    // each on a path that only runs when they've already disagreed.
372	    console.warn("Fringe Planner: catalogue/availability mismatch, refetching both —", verdict.why);
373	    await Promise.all([evictCached(DATA_URL), evictCached(AVAILABILITY_URL)]);
374	  }
375	}
