155	
156	function readStore(key, fallback) {
157	  try {
158	    const raw = localStorage.getItem(key);
159	    return raw ? JSON.parse(raw) : fallback;
160	  } catch {
161	    // A blocked or full localStorage is a working page with no memory, not a
162	    // broken one.
163	    return fallback;
164	  }
165	}
166	
167	function writeStore(key, value) {
168	  try {
169	    localStorage.setItem(key, JSON.stringify(value));
170	  } catch {
171	    /* see readStore */
172	  }
173	}
