179	function savePrefs() {
180	  writeStore(KEY_PREFS, {
181	    d0: state.d0,
182	    d1: state.d1,
183	    dayStartMin: state.dayStartMin,
184	    dayEndMin: state.dayEndMin,
185	    meals: state.meals,
186	    minPerDay: state.minPerDay,
187	    maxPerDay: state.maxPerDay,
188	    minGap: state.minGap,
189	    mode: state.mode,
190	  });
191	}
192	
193	function restorePrefs() {
194	  const saved = readStore(KEY_PREFS, null);
195	  if (!saved) return;
196	  const n = state.dates.length;
197	  state.d0 = clamp(Number(saved.d0) || 1, 1, n);
198	  state.d1 = clamp(Number(saved.d1) || n, state.d0, n);
199	  state.dayStartMin = Number.isFinite(saved.dayStartMin) ? saved.dayStartMin : state.dayStartMin;
200	  state.dayEndMin = Number.isFinite(saved.dayEndMin) ? saved.dayEndMin : state.dayEndMin;
201	  if (Array.isArray(saved.meals)) {
202	    for (const meal of state.meals) {
203	      const stored = saved.meals.find((m) => m && m.id === meal.id);
204	      if (stored) Object.assign(meal, { enabled: !!stored.enabled, startMin: stored.startMin, endMin: stored.endMin });
205	    }
206	  }
207	  state.minPerDay = Number(saved.minPerDay) || state.minPerDay;
208	  state.maxPerDay = Number(saved.maxPerDay) || state.maxPerDay;
209	  state.minGap = Number.isFinite(saved.minGap) ? saved.minGap : state.minGap;
210	  if (MODE_META[saved.mode]) state.mode = saved.mode;
211	}
