362	/** The verdict pill each lane wears, mirroring the plan. */
363	function applyVerdicts(summary, diagnostics) {
364	  const bySlug = new Map(summary.shows.map((s) => [s.slug, s]));
365	  for (const lane of $("lanes").querySelectorAll(".lane")) {
366	    const slug = lane.dataset.slug;
367	    const show = bySlug.get(slug);
368	    const scheduled = state.scheduledSlugs.has(slug);
369	    const inWindow = show ? show.performances.some((p) => p.inWindow) : false;
370	    lane.classList.toggle("lane--scheduled", scheduled);
371	    lane.classList.toggle("lane--forced", state.forced.has(slug));
372	    lane.classList.toggle("lane--out", !inWindow);
373	    lane.classList.toggle("lane--blocked", diagnostics.blockedSlugs.has(slug));
374	
375	    // The pill's emoji is the page's, not the translation's: a marker a
376	    // translator cannot lose, beside a word that is entirely theirs.
377	    const [verdictClass, verdictKey, verdictMark] = scheduled
378	      ? ["st-plan st-in", "lane.scheduled", "✓"]
379	      : !inWindow
380	        ? ["st-dates st-no", "lane.noDates", "📅"]
381	        : diagnostics.blockedSlugs.has(slug)
382	          ? ["st-conflict st-warn", "lane.outsideHours", "⏰"]
383	          : ["st-cant", "lane.cantFit", ""];
384	    const statusEl = lane.querySelector(".lane-status");
385	    statusEl.innerHTML =
386	      `<span class="${verdictClass}" data-i18n-slot="${verdictKey}">` +
387	      (verdictMark ? `<span aria-hidden="true">${verdictMark}</span> ` : "") +
388	      `${escapeHtml(t(verdictKey))}</span>`;
389	
390	    // Ring the one performance the plan picked, the way the Fringe grid does.
391	    const picked = state.selectedSlot.get(slug);
392	    for (const cell of lane.querySelectorAll(".cell")) {
393	      let pinned = false;
394	      for (const seg of cell.querySelectorAll(".seg")) {
395	        // slotKey()'s own spelling — the map is keyed by the engine, so the
396	        // grid has to ask the question in the engine's words.
397	        const isPick = picked === `${seg.dataset.date}T${seg.dataset.start}`;
398	        seg.classList.toggle("seg--selected", isPick);
399	        if (isPick) pinned = true;
400	      }
401	      cell.classList.toggle("cell--pin", pinned && state.forced.has(slug));
402	    }
403	  }
404	}
