406	// --- the date window ------------------------------------------------------
407	
408	function layoutOverlay() {
409	  const daysEl = $("dayHead");
410	  const dr = daysEl.getBoundingClientRect();
411	  if (dr.width === 0) return;
412	  const wr = $("calInner").getBoundingClientRect();
413	  state.layout = {
414	    trackLeft: dr.left - wr.left,
415	    trackWidth: dr.width,
416	    dayW: dr.width / state.dates.length,
417	  };
418	  const win = $("win");
419	  win.style.left = state.layout.trackLeft + "px";
420	  win.style.width = state.layout.trackWidth + "px";
421	  paintWindow();
422	}
423	
424	/* The overlay is positioned in physical pixels over a grid whose columns follow
425	 * the page's direction, so on a right-to-left page day 1 is the rightmost
426	 * column and every x below is measured from the other end. `boundaryX` is the
427	 * one place that knows it; the rest of the window's maths is direction-blind. */
428	const isRtl = () => currentDir() === "rtl";
429	
430	/** The physical offset of the boundary `days` days after the first night. */
431	function boundaryX(days) {
432	  const { trackWidth, dayW } = state.layout;
433	  return isRtl() ? trackWidth - days * dayW : days * dayW;
434	}
435	
436	function paintWindow() {
437	  const { trackLeft, trackWidth } = state.layout;
438	  const x0 = boundaryX(state.d0 - 1);
439	  const x1 = boundaryX(state.d1);
440	  // The window's own edges keep their logical identity; the dimmed regions and
441	  // the band are whatever lies outside and inside them on screen.
442	  const near = Math.min(x0, x1);
443	  const far = Math.max(x0, x1);
444	  $("dimL").style.cssText = `left:0;width:${near}px`;
445	  $("dimR").style.cssText = `left:${far}px;width:${Math.max(0, trackWidth - far)}px`;
446	  $("band").style.cssText = `left:${near}px;width:${far - near}px`;
447	  $("edgeStart").style.left = `${x0}px`;
448	  $("edgeEnd").style.left = `${x1}px`;
449	  $("hStart").style.left = `${trackLeft + x0}px`;
450	  $("hEnd").style.left = `${trackLeft + x1}px`;
451	  $("railBand").style.cssText = `left:${trackLeft + near}px;width:${far - near}px`;
452	  $("flagStart").textContent = dayLabel(windowStartISO());
453	  $("flagEnd").textContent = dayLabel(windowEndISO());
454	  const len = state.d1 - state.d0 + 1;
455	  $("railLen").textContent = t("rail.nights", { count: len });
456	  for (const [el, value, iso] of [
457	    [$("hStart"), state.d0, windowStartISO()],
458	    [$("hEnd"), state.d1, windowEndISO()],
459	  ]) {
460	    el.setAttribute("aria-valuemax", String(state.dates.length));
461	    el.setAttribute("aria-valuenow", String(value));
462	    el.setAttribute("aria-valuetext", dayAndDate(iso));
463	  }
464	}
465	
466	function dayAt(clientX) {
467	  const wr = $("calInner").getBoundingClientRect();
468	  const { trackLeft, trackWidth, dayW } = state.layout;
469	  const x = clientX - wr.left - trackLeft;
470	  return clamp(Math.round((isRtl() ? trackWidth - x : x) / dayW), 0, state.dates.length);
471	}
472	
473	function dragDate(el, apply) {
474	  el.addEventListener("pointerdown", (e) => {
475	    e.preventDefault();
476	    el.setPointerCapture(e.pointerId);
477	    el.classList.add("dragging");
478	    const startX = e.clientX;
479	    const s0 = state.d0;
480	    const s1 = state.d1;
481	    const move = (ev) => {
482	      apply(ev, s0, s1, startX);
483	      paintWindow();
484	      replan();
485	    };
486	    const up = () => {
487	      el.classList.remove("dragging");
488	      el.removeEventListener("pointermove", move);
489	      el.removeEventListener("pointerup", up);
490	    };
491	    el.addEventListener("pointermove", move);
492	    el.addEventListener("pointerup", up);
493	  });
494	}
495	
496	function keysDate(el, fn) {
497	  el.addEventListener("keydown", (e) => {
498	    // The arrow that moves the window later is the one that points along the
499	    // page's reading direction, which is the way the grid itself runs.
500	    const later = isRtl() ? "ArrowLeft" : "ArrowRight";
501	    const step = e.key === later ? 1 : e.key === (isRtl() ? "ArrowRight" : "ArrowLeft") ? -1 : 0;
502	    if (!step) return;
503	    e.preventDefault();
504	    fn(step);
505	    paintWindow();
506	    replan();
507	  });
508	}
509	
510	function wireWindow() {
511	  const n = () => state.dates.length;
512	  dragDate($("hStart"), (ev) => {
513	    state.d0 = clamp(dayAt(ev.clientX) + 1, 1, state.d1);
514	  });
515	  dragDate($("edgeStart"), (ev) => {
516	    state.d0 = clamp(dayAt(ev.clientX) + 1, 1, state.d1);
517	  });
518	  dragDate($("hEnd"), (ev) => {
519	    state.d1 = clamp(dayAt(ev.clientX), state.d0, n());
520	  });
521	  dragDate($("edgeEnd"), (ev) => {
522	    state.d1 = clamp(dayAt(ev.clientX), state.d0, n());
523	  });
524	  dragDate($("band"), (ev, s0, s1, startX) => {
525	    const travelled = (ev.clientX - startX) * (isRtl() ? -1 : 1);
526	    const shift = Math.round(travelled / state.layout.dayW);
527	    const span = s1 - s0;
528	    const d0 = clamp(s0 + shift, 1, n() - span);
529	    state.d0 = d0;
530	    state.d1 = d0 + span;
531	  });
532	  keysDate($("hStart"), (step) => {
533	    state.d0 = clamp(state.d0 + step, 1, state.d1);
534	  });
535	  keysDate($("hEnd"), (step) => {
536	    state.d1 = clamp(state.d1 + step, state.d0, n());
537	  });
538	  addEventListener("resize", layoutOverlay);
539	}
