630	// --- the schedule board ---------------------------------------------------
631	
632	function renderSchedule(schedule) {
633	  const host = $("schedule");
634	  const empty = $("scheduleEmpty");
635	  host.innerHTML = "";
636	  if (!schedule.scheduled.length) {
637	    host.hidden = true;
638	    empty.hidden = false;
639	    return;
640	  }
641	  host.hidden = false;
642	  empty.hidden = true;
643	
644	  const mins = [AXIS_TOP_MIN, state.dayStartMin];
645	  const maxs = [AXIS_BOTTOM_MIN, state.dayEndMin];
646	  for (const slot of schedule.scheduled) {
647	    mins.push(slot.startMinuteOfDay);
648	    maxs.push(slot.endMinuteOfDay);
649	  }
650	  for (const meal of state.meals) {
651	    if (!meal.enabled) continue;
652	    mins.push(meal.startMin);
653	    maxs.push(meal.endMin);
654	  }
655	  const minHour = Math.floor(Math.max(0, Math.min(...mins)) / 60);
656	  const maxHour = Math.max(minHour + 1, Math.ceil(Math.max(...maxs) / 60));
657	  const axisTopMin = minHour * 60;
658	  const axisBottomMin = maxHour * 60;
659	  const axisH = (maxHour - minHour) * SCH_HOUR_PX;
660	  const y = (min) => ((clamp(min, axisTopMin, axisBottomMin) - axisTopMin) / 60) * SCH_HOUR_PX;
661	
662	  host.style.setProperty("--sch-hour-h", `${SCH_HOUR_PX}px`);
663	  host.style.setProperty("--sch-head-h", `${SCH_HEAD_PX}px`);
664	
665	  const gutter = document.createElement("div");
666	  gutter.className = "sch-gutter";
667	  const gHead = document.createElement("div");
668	  gHead.className = "sch-gutter-head";
669	  const gBody = document.createElement("div");
670	  gBody.className = "sch-gutter-body";
671	  gBody.style.height = `${axisH}px`;
672	  for (let h = minHour; h <= maxHour; h++) {
673	    const label = document.createElement("div");
674	    label.className = "sch-hour" + (h >= 24 ? " sch-hour--late" : "");
675	    label.style.top = `${(h - minHour) * SCH_HOUR_PX}px`;
676	    label.textContent = `${pad2(h)}:00`;
677	    gBody.appendChild(label);
678	  }
679	  gutter.append(gHead, gBody);
680	  host.appendChild(gutter);
681	
682	  const byDate = new Map(schedule.days.map((d) => [d.date, d]));
683	  const renderDays = state.dates
684	    .slice(state.d0 - 1, state.d1)
685	    .map((iso) => byDate.get(iso) || { date: iso, slots: [] });
686	
687	  const wrapW = ($("scheduleWrap").clientWidth || 800) - SCH_GUTTER_PX;
688	  const emptyCount = renderDays.filter((d) => !d.slots.length).length;
689	  const fullCount = Math.max(1, renderDays.length - emptyCount);
690	  const colW = Math.max(1, (wrapW - emptyCount * SCH_EMPTY_COL_PX) / fullCount);
691	  host.classList.toggle("cols-narrow", colW < 78);
692	  host.classList.toggle("cols-tiny", colW < 56);
693	
694	  for (const day of renderDays) {
695	    const full = day.slots.length > 0;
696	    const col = document.createElement("div");
697	    col.className = "sch-day" + (isWeekend(day.date) ? " wknd" : "") + (full ? "" : " sch-day--empty");
698	    col.dataset.date = day.date;
699	
700	    const head = document.createElement("div");
701	    head.className = "sch-day-head";
702	    head.innerHTML = full
703	      ? `<div class="sch-dow">${escapeHtml(dates({ weekday: "long" }).format(dateOf(day.date)))} ` +
704	        `<span class="sch-date">${escapeHtml(dayLabel(day.date))}</span></div>` +
705	        `<div class="sch-day-count" data-i18n-slot="schedule.dayCount">` +
706	        `${escapeHtml(t("schedule.dayCount", { count: day.slots.length }))}</div>`
707	      : `<div class="sch-dow sch-dow--empty">${dateOf(day.date).getUTCDate()}</div>`;
708	    if (!full) col.title = t("schedule.nothingPlanned", { day: dayAndDate(day.date) });
709	
710	    const body = document.createElement("div");
711	    body.className = "sch-body";
712	    body.style.height = `${axisH}px`;
713	
714	    for (let i = 0; i < day.slots.length - 1; i++) {
715	      const a = day.slots[i];
716	      const b = day.slots[i + 1];
717	      const gap = b.startMinuteOfDay - a.endMinuteOfDay;
718	      if (gap < 0 || gap >= 60) continue;
719	      body.appendChild(buildTravelLeg(a, b, y(a.endMinuteOfDay), y(b.startMinuteOfDay)));
720	    }
721	    for (const slot of day.slots) {
722	      body.appendChild(buildScheduleBlock(slot, y(slot.startMinuteOfDay), y(slot.endMinuteOfDay)));
723	    }
724	
725	    col.append(head, body);
726	    host.appendChild(col);
727	  }
728	}
