730	function buildScheduleBlock(slot, top, rawBottom) {
731	  const height = Math.max(SCH_MIN_BLOCK, rawBottom - top);
732	  const forced = state.forced.has(slot.slug);
733	  const block = document.createElement("a");
734	  block.className =
735	    "sch-show " + (slot.status === "FREE_NON_TICKETED" ? "seg-free" : "seg-avail") +
736	    (forced ? " sch-show--pinned" : "");
737	  block.href = slot.url;
738	  block.target = "_blank";
739	  block.rel = "noopener";
740	  block.draggable = false;
741	  block.style.top = `${top}px`;
742	  block.style.height = `${height}px`;
743	  block.dataset.slug = slot.slug;
744	  if (height < SCH_TIGHT_PX) block.classList.add("sch-show--tight");
745	
746	  // A show with no published running time has end === start, so the clock
747	  // would read "22:00–22:00". Say the start and stop there rather than draw a
748	  // length nobody published.
749	  const end = slotEndTime(slot);
750	  const timeStr = end === slot.startTime ? slot.startTime : `${slot.startTime}–${end}`;
751	  block.innerHTML =
752	    (forced ? `<span class="sch-pin" aria-hidden="true">🔒</span>` : "") +
753	    `<span class="sch-body-text">` +
754	    `<span class="sch-name">${foreign(slot.title)}</span>` +
755	    `<span class="sch-meta">` +
756	    `<span class="sch-time">${escapeHtml(timeStr)}</span>` +
757	    (slot.venueName ? `<span class="sch-venue">${foreign(slot.venueName)}</span>` : "") +
758	    `</span></span>`;
759	  return block;
760	}
