762	function buildTravelLeg(a, b, top, bottom) {
763	  const leg = document.createElement("div");
764	  leg.className = "sch-leg";
765	  leg.style.top = `${top}px`;
766	  leg.style.height = `${Math.max(0, bottom - top)}px`;
767	
768	  const gapMin = Math.max(0, b.startMinuteOfDay - a.endMinuteOfDay);
769	  const meta = MODE_META[state.mode];
770	  const km1 = (km) =>
771	    new Intl.NumberFormat(currentIntlLocale(), { maximumFractionDigits: 1, minimumFractionDigits: 1 }).format(km);
772	  let text;
773	  let title;
774	  let key;
775	  if (a.venueCode && b.venueCode && a.venueCode === b.venueCode) {
776	    key = "leg.sameVenue";
777	    text = t(key, { gap: gapMin });
778	    title = t("leg.sameVenue.tip", { venue: a.venueName || "", gap: gapMin });
779	  } else {
780	    const km = distanceKm({ lat: a.venueLat, lng: a.venueLng }, { lat: b.venueLat, lng: b.venueLng });
781	    const mins = travelMinutes(
782	      { lat: a.venueLat, lng: a.venueLng },
783	      { lat: b.venueLat, lng: b.venueLng },
784	      state.mode
785	    );
786	    if (km == null || mins == null) {
787	      key = "leg.nearby";
788	      text = t(key, { gap: gapMin });
789	      title = t("leg.unknown.tip");
790	    } else {
791	      const spare = Math.round(gapMin - mins);
792	      key = "leg.travel";
793	      text = t(key, {
794	        minutes: Math.round(mins),
795	        km: km1(km),
796	        spare: `${spare >= 0 ? "+" : ""}${spare}`,
797	      });
798	      title = t("leg.travel.tip", {
799	        minutes: Math.round(mins),
800	        mode: t(meta.verbKey),
801	        km: km1(km),
802	        gap: gapMin,
803	        spare,
804	      });
805	    }
806	  }
807	  leg.title = title;
808	  leg.dataset.i18nSlot = key;
809	  leg.innerHTML =
810	    `<span class="leg-emoji" aria-hidden="true">${meta.emoji}</span>` +
811	    `<span class="leg-text">${escapeHtml(text)}</span>`;
812	  return leg;
813	}
