1202	    if (culprits.length === 2 && culprits[0] === "lunch" && culprits[1] === "dinner") return { kind: "meal" };
1203	    if (culprits.length > 1) return { kind: "combo", kinds: culprits };
1204	    // Blocked by the day-hours/meal filter, yet no *single* control would rescue
1205	    // it: every performance trips two settings at once (say, a long show that
1206	    // spans lunch and runs past the day end). Still a settings problem, not a
1207	    // clash — say so, with no one control to name.
1208	    if (sets.blockedSet.has(show.slug)) return { kind: "combo", kinds: [] };
