1215	  const runSold = perfs.length > 0 && perfs.every((p) => p.soldOut);
1216	  const windowSold = inWindow.length > 0 && inWindow.every((p) => p.soldOut);
1217	  if (runSold || windowSold) return { kind: "sold" };
