2759	// --- "Pick my best dates": place the window where it catches the most shows --
2760	
2761	function windowScore(d0, d1) {
2762	  const a = dateStr(d0);
2763	  const b = dateStr(d1);
2764	  let shows = 0;
2765	  let dates = 0;
2766	  for (const show of state.matched) {
2767	    let n = 0;
2768	    for (const p of show.performances || []) {
2769	      if (p.date >= a && p.date <= b && isAvailable(p)) n++;
2770	    }
2771	    if (n > 0) shows++;
2772	    dates += n;
2773	  }
2774	  return { shows, dates };
2775	}
2776	
2777	/** Count the weekend days (Sat/Sun) within an inclusive day-of-month range. */
2778	function weekendDays(d0, d1) {
2779	  let n = 0;
2780	  for (let d = d0; d <= d1; d++) if (isWeekend(d)) n++;
2781	  return n;
2782	}
2783	
2784	/**
2785	 * Best placement for a fixed-length window. Without "weekends", it maximises
2786	 * shows caught (then catchable dates). With "weekends" on, it first maximises
2787	 * the weekend days the window covers — so the trip lands on the busiest Fringe
2788	 * days — then breaks ties by shows, then dates.
2789	 */
2790	function optimizeDates(days, weekends) {
2791	  const len = clamp(days, 1, DAYS_IN_MONTH);
2792	  let best = null;
2793	  for (let d0 = 1; d0 + len - 1 <= DAYS_IN_MONTH; d0++) {
2794	    const d1 = d0 + len - 1;
2795	    const score = windowScore(d0, d1);
2796	    const cand = { d0, d1, wknd: weekends ? weekendDays(d0, d1) : 0, ...score };
2797	    if (!best) { best = cand; continue; }
2798	    const better = weekends
2799	      ? cand.wknd > best.wknd ||
2800	        (cand.wknd === best.wknd && (cand.shows > best.shows || (cand.shows === best.shows && cand.dates > best.dates)))
2801	      : cand.shows > best.shows || (cand.shows === best.shows && cand.dates > best.dates);
2802	    if (better) best = cand;
2803	  }
2804	  return best;
2805	}
2806	
2807	/** The optimizer, folded into the window bar: an "Optimize?" link on the
2808	 *  draggable centre band opens a small popover (day count + weekends toggle). */
2809	function wireWindowOptimizer() {
2810	  const btn = $("railOptBtn");
2811	  const pop = $("railPop");
2812	  if (!btn || !pop) return;
2813	
2814	  const setOpen = (open) => {
2815	    btn.setAttribute("aria-expanded", String(open));
2816	    if (!open) { pop.hidden = true; return; }
2817	    $("optDays").value = String(state.d1 - state.d0 + 1);
2818	    pop.hidden = false; // unhide first so we can measure it
2819	    const r = btn.getBoundingClientRect();
2820	    const pw = pop.offsetWidth;
2821	    pop.style.top = `${r.bottom + 6}px`;
2822	    pop.style.left = `${clamp(r.left + r.width / 2 - pw / 2, 8, window.innerWidth - pw - 8)}px`;
2823	  };
2824	
2825	  // Keep clicks/drags on the control from starting a window drag or bubbling to
2826	  // the document "click-away" closer.
2827	  btn.addEventListener("pointerdown", (e) => e.stopPropagation());
2828	  pop.addEventListener("pointerdown", (e) => e.stopPropagation());
2829	  pop.addEventListener("click", (e) => e.stopPropagation());
2830	  btn.addEventListener("click", (e) => {
2831	    e.stopPropagation();
2832	    setOpen(pop.hidden);
2833	  });
2834	  document.addEventListener("click", (e) => {
2835	    if (!pop.hidden && e.target !== btn && !pop.contains(e.target)) setOpen(false);
2836	  });
2837	  document.addEventListener("keydown", (e) => {
2838	    if (e.key === "Escape" && !pop.hidden) { setOpen(false); btn.focus(); }
2839	  });
2840	
2841	  $("optApplyBtn").addEventListener("click", () => {
2842	    if (state.matched.length === 0) { setOpen(false); return; }
2843	    const days = clamp(Number($("optDays").value) || 1, 1, DAYS_IN_MONTH);
2844	    const best = optimizeDates(days, $("optWeekends").checked);
2845	    setOpen(false);
2846	    if (!best) return;
2847	    state.d0 = best.d0;
2848	    state.d1 = best.d1;
2849	    paintWindow(true); // glide the window lines to the chosen dates
2850	    refresh();
