2854	// --- The day-mark popup ----------------------------------------------------
2855	
2856	/** The matched show a lane is showing, by slug. */
2857	function showBySlug(slug) {
2858	  return state.matched.find((s) => s.slug === slug) || null;
2859	}
2860	
2861	/** Text cut to `max` characters on a word boundary, with an ellipsis when it
2862	 *  actually had to cut. */
2863	function trimTo(text, max) {
2864	  const s = String(text || "").trim();
2865	  if (s.length <= max) return s;
2866	  return s.slice(0, max).replace(/\s+\S*$/, "") + "…";
2867	}
2868	
2869	/**
2870	 * The popup for one day cell: the show, that day's performances with their
2871	 * ticket status, what the plan did with them, and a line of description when
2872	 * the sidecar has arrived (see loadDescriptions — it may never arrive, and the
2873	 * card is complete without it).
2874	 *
2875	 * @param {HTMLElement} lane the .lane the cell belongs to (carries the slug)
2876	 * @param {HTMLElement} cell the hovered .cell (carries the day of month)
2877	 * @returns {string} popup HTML, or "" when there's nothing to say
2878	 */
2879	function buildCellTip(lane, cell) {
2880	  const show = showBySlug(lane.dataset.slug);
2881	  const day = Number(cell.dataset.day);
2882	  if (!show || !day) return "";
2883	
2884	  const date = `${YEAR}-${MONTH}-${String(day).padStart(2, "0")}`;
2885	  const perfs = show.performances
2886	    .filter((p) => p.date === date)
2887	    .sort((a, b) => a.start.localeCompare(b.start));
2888	  if (perfs.length === 0) return "";
2889	
2890	  const selectedKey = state.selectedSlot.get(show.slug) || null;
2891	  const pin = state.forced.get(show.slug);
2892	  const pinnedKey = typeof pin === "string" ? pin : null;
2893	
2894	  const rows = perfs
2895	    .map((p) => {
2896	      const key = slotKey({ date: p.date, start: p.start });
2897	      const planned = selectedKey != null && key === selectedKey;
2898	      const pinned = pinnedKey != null && key === pinnedKey;
2899	      const note = pinned ? "locked into your plan" : planned ? "in your plan" : statusLabel(p);
2900	      return (
2901	        `<li class="tip-perf${planned || pinned ? " tip-perf--planned" : ""}">` +
2902	        // Same classes the grid mark itself wears, so the swatch and the bar it
2903	        // describes can never drift apart.
2904	        `<i class="seg ${planned || pinned ? "seg--selected" : segClass(p)}"></i>` +
2905	        `<b>${escapeHtml(p.start)}</b>` +
2906	        `<span class="tip-status">${escapeHtml(note)}</span>` +
2907	        `</li>`
2908	      );
2909	    })
2910	    .join("");
2911	
2912	  const meta = [show.genre, show.venueName].filter(Boolean).map(escapeHtml).join(" · ");
2913	  // A full description can run several paragraphs; the card is a glance, not a
2914	  // programme entry, so it shows the opening and stops on a word boundary.
2915	  const desc = trimTo(descriptionFor(show.slug), 240);
2916	  const hint = pinnedKey != null && perfs.some((p) => slotKey(p) === pinnedKey)
2917	    ? "Click the locked mark to unlock it"
2918	    : "Click a mark to lock that performance in";
2919	
2920	  return (
2921	    `<p class="tip-title">${escapeHtml(show.title)}</p>` +
2922	    (meta ? `<p class="tip-meta">${meta}</p>` : "") +
2923	    `<p class="tip-date">${dowShort(day)} ${day} Aug</p>` +
2924	    `<ul class="tip-perfs">${rows}</ul>` +
2925	    (desc ? `<p class="tip-desc">${escapeHtml(desc)}</p>` : "") +
2926	    `<p class="tip-hint">${hint}</p>`
2927	  );
2928	}
2929	
2930	function wireCellTips() {
2931	  const lanes = $("lanes");
2932	  const tip = $("calTip");
2933	  let shownFor = null; // the cell the popup currently describes
2934	
2935	  /* Anchored to the cell, not the cursor: centred on the mark, above it when
2936	   * there's room and below it when there isn't, and always clamped inside the
2937	   * viewport. */
2938	  const position = (cell) => {
2939	    const gap = 10;
2940	    const r = cell.getBoundingClientRect();
2941	    const w = tip.offsetWidth;
2942	    const h = tip.offsetHeight;
2943	    let x = r.left + r.width / 2 - w / 2;
2944	    x = Math.min(Math.max(8, x), window.innerWidth - w - 8);
2945	    let y = r.top - h - gap;
2946	    if (y < 8) y = r.bottom + gap;
2947	    tip.style.left = `${x}px`;
2948	    tip.style.top = `${y}px`;
2949	  };
2950	
2951	  const hide = () => {
2952	    tip.hidden = true;
2953	    shownFor = null;
2954	  };
2955	
2956	  lanes.addEventListener("pointerover", (e) => {
2957	    const cell = e.target.closest(".cell");
2958	    const lane = cell && cell.closest(".lane");
2959	    if (!cell || !lane || !cell.dataset.day) {
2960	      hide();
2961	      return;
2962	    }
2963	    if (cell === shownFor) return; // same mark — leave the card where it is
2964	    const html = buildCellTip(lane, cell);
2965	    if (!html) {
2966	      hide();
2967	      return;
2968	    }
2969	    tip.innerHTML = html;
2970	    delete tip.dataset.conflict; // this card is a day mark, not a conflict
2971	    tip.hidden = false;
2972	    shownFor = cell;
2973	    position(cell);
2974	  });
2975	  lanes.addEventListener("pointerleave", hide);
2976	  calWrap().addEventListener("scroll", hide);
2977	  window.addEventListener("resize", hide);
2978	}
2979	
2980	// --- Screen 3: the plan ----------------------------------------------------
2981	
2982	const SCH_HOUR_PX = 34; // the axis now spans a fixed 09:00–27:00 (18h), so a
2983	                        // shorter hour keeps the whole night on one calm board
2984	const SCH_MIN_BLOCK = 34;
2985	/* Below this, a block can't carry a two-line title *and* its meta line, so the
2986	 * start–end time goes and the title clamps to one line — the axis beside the
2987	 * block already says when it is, and the venue is the fact you can't get
2988	 * anywhere else. Blocks never fall below SCH_MIN_BLOCK, and a floor-height
2989	 * block still fits a title line plus the meta line comfortably. */
2990	const SCH_TIGHT_PX = 42;
2991	// The width of a day with nothing planned in it. Wide enough to carry the date
2992	// and read as a day, narrow enough that a fortnight of blanks doesn't squeeze
2993	// the days you're actually going out on.
2994	const SCH_EMPTY_COL_PX = 30;
2995	const SCH_HEAD_PX = 46;
2996	const SCH_GUTTER_PX = 52;
2997	
2998	const DOW_LONG = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
