3641	// ~96px per inch; 5 emoji per square inch → one cell every 96/√5 ≈ 43px.
3642	const DECOR_CELL_PX = 43;
3643	
3644	/** A stable 0..1 pseudo-random from three integers (cell x, cell y, salt). */
3645	function decorHash(x, y, salt) {
3646	  let h = (Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(salt, 83492791)) >>> 0;
3647	  h ^= h >>> 13;
3648	  h = Math.imul(h, 0x5bd1e995) >>> 0;
3649	  h ^= h >>> 15;
3650	  return (h >>> 0) / 4294967296;
3651	}
3652	
3653	/** A small integer seed from a string, so different regions scatter differently. */
3654	function decorSalt(str) {
3655	  let h = 2166136261;
3656	  for (let i = 0; i < str.length; i++) h = Math.imul(h ^ str.charCodeAt(i), 16777619);
3657	  return h >>> 0;
3658	}
