3660	function buildDecorHTML(w, h, setName, seed) {
3661	  const set = DECOR_SETS[setName] || DECOR_SETS.food;
3662	  const salt = decorSalt(`${seed}:${setName}`);
3663	  const cols = Math.max(1, Math.ceil(w / DECOR_CELL_PX));
3664	  const rows = Math.max(1, Math.ceil(h / DECOR_CELL_PX));
3665	  let html = "";
3666	  for (let j = 0; j < rows; j++) {
3667	    for (let i = 0; i < cols; i++) {
3668	      const jx = (decorHash(i, j, salt + 1) - 0.5) * DECOR_CELL_PX * 0.8;
3669	      const jy = (decorHash(i, j, salt + 2) - 0.5) * DECOR_CELL_PX * 0.8;
3670	      const cx = i * DECOR_CELL_PX + DECOR_CELL_PX / 2 + jx;
3671	      const cy = j * DECOR_CELL_PX + DECOR_CELL_PX / 2 + jy;
3672	      if (cx < 0 || cx > w || cy < 0 || cy > h) continue;
3673	      const emoji = set[Math.floor(decorHash(i, j, salt + 3) * set.length)];
3674	      const size = (11 + decorHash(i, j, salt + 4) * 13).toFixed(1);
3675	      const rot = Math.round(decorHash(i, j, salt + 5) * 80 - 40);
3676	      const op = (0.55 + decorHash(i, j, salt + 6) * 0.45).toFixed(2);
3677	      html += `<span style="left:${cx.toFixed(1)}px;top:${cy.toFixed(1)}px;font-size:${size}px;opacity:${op};transform:translate(-50%,-50%) rotate(${rot}deg)">${emoji}</span>`;
3678	    }
3679	  }
3680	  return html;
3681	}
